(()=>{'use strict';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const safe=s=>/^(https?:\/\/|\/[^/])/.test(s||'')?s:'';const root=document.querySelector('[data-business]');if(!root)return;const b=JSON.parse(root.dataset.business);const all=JSON.parse(document.querySelector('#business-data').textContent);const digits=String(b.phone||'').replace(/\D/g,''),phone=digits.startsWith('0')?'598'+digits.slice(1):digits;const wa=msg=>'https://wa.me/'+phone+'?text='+encodeURIComponent(msg);const track=action=>{const event={businessId:b.id,action,at:new Date().toISOString(),source:new URLSearchParams(location.search).get('src')==='qr'?'qr':'web'};try{const key='revista-metrics-demo-v1',rows=JSON.parse(localStorage.getItem(key)||'[]');rows.push(event);localStorage.setItem(key,JSON.stringify(rows.slice(-500)))}catch{}if(window.REVISTA_METRICS_ENDPOINT)fetch(window.REVISTA_METRICS_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event),keepalive:true}).catch(()=>{})};track('view');if(new URLSearchParams(location.search).get('src')==='qr')track('qr_access');document.addEventListener('click',e=>{const el=e.target.closest('[data-track]');if(el)track(el.dataset.track)});
const section=(title,content,id='')=>`<section class="module" ${id?`id="${id}"`:''}><h2>${title}</h2>${content}</section>`;const empty=text=>`<p class="empty">${text}</p>`;const contact=(label,msg)=>`<a class="btn" data-track="whatsapp" href="${esc(wa(msg))}" target="_blank" rel="noopener">${label}</a>`;const image=(src,alt)=>safe(src)?`<img src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`:'';let html='';if(b.type==='realEstate')html+=`<div class="grid two"><section class="module"><h2>¿QUERÉS COMPRAR?</h2>${contact('BUSCAR UNA PROPIEDAD','Hola Moravia, vi tu ficha en Revista Montevideo. Estoy buscando una propiedad para comprar.')}</section><section class="module"><h2>¿QUERÉS VENDER?</h2>${contact('QUIERO VENDER MI PROPIEDAD','Hola Moravia, vi tu ficha en Revista Montevideo. Quiero vender mi propiedad.')}</section></div>`;
html+=section(b.type==='realEstate'?'CONOCÉ A MORAVIA':'CONOCÉ EL NEGOCIO',b.about?`<p>${esc(b.about)}</p>`:b.type==='realEstate'?'<p>Moravia Díaz · Agente Inmobiliaria · RE/MAX Rambla.</p><p>Compra, venta y asesoramiento inmobiliario en Montevideo.</p>':`<p>${esc(b.description)}</p>`);
html+=section('CONOCÉ MI FORMA DE TRABAJAR',safe(b.video)?`<video controls playsinline preload="metadata" ${safe(b.videoPoster)?`poster="${esc(b.videoPoster)}"`:''}><source src="${esc(b.video)}">Tu navegador no admite este video. <a href="${esc(b.video)}">Abrir video</a></video>`:empty('Próximamente, un video para conocer su forma de trabajar.'));
const moduleTypes={realEstate:{key:'properties',title:'PROPIEDADES DESTACADAS',all:'VER TODAS LAS PROPIEDADES',empty:'Consultá a Moravia por las propiedades disponibles.'},commerce:{key:'products',title:'PRODUCTOS DESTACADOS',all:'VER TODOS LOS PRODUCTOS',empty:'Consultá productos y disponibilidad.'},service:{key:'works',title:'TRABAJOS REALIZADOS',all:'VER TODOS LOS TRABAJOS',empty:'Próximamente, trabajos realizados y sus etapas.'}};const cfg=moduleTypes[b.type];if(cfg){const rows=b.modules?.[cfg.key]||[];const cards=rows.map((p,i)=>`<article class="item" ${i>=3?'hidden data-extra-item':''}>${image(p.photo,p.title)}<h3>${esc(p.title)}</h3>${p.area?`<p>${esc(p.area)}</p>`:''}${p.price?`<strong>${esc(p.price)}</strong>`:''}<p class="property-meta">${[['Dormitorios',p.bedrooms],['Baños',p.bathrooms],['m²',p.squareMeters]].filter(([,v])=>v!==undefined&&v!=='').map(([k,v])=>`<span>${esc(v)} ${k}</span>`).join('')}</p><p>${esc(p.description||'')}</p>${p.promotion?`<p>${esc(p.promotion)}</p>`:''}${['before','during','after'].map(k=>p[k]?`<figure>${image(p[k],{before:'Antes',during:'Durante',after:'Después'}[k])}<figcaption>${{before:'Antes',during:'Durante',after:'Después'}[k]}</figcaption></figure>`:'').join('')}<a class="btn" data-track="${cfg.key}_interaction" href="${esc(safe(p.url)||wa('Hola, vi '+(p.title||'esta publicación')+' en Revista Montevideo. Quiero consultar.'))}" target="_blank" rel="noopener">${safe(p.url)?'Ver propiedad':'Consultar'}</a></article>`).join('');html+=section(cfg.title,rows.length?`<div class="grid">${cards}</div>${rows.length>3?`<button class="btn" id="show-all">${cfg.all}</button>`:`<a class="btn" data-track="${cfg.key}_interaction" href="${esc(wa('Hola, quiero conocer todas las opciones disponibles. Vengo de Revista Montevideo.'))}">${cfg.all}</a>`}`:empty(cfg.empty)+contact(cfg.all,'Hola, vengo de Revista Montevideo. Quiero conocer las opciones disponibles.'),'destacados')}
html+=section(b.type==='realEstate'?'CONSEJOS DE MORAVIA':'CONSEJOS PROFESIONALES',(b.advice||[]).length?b.advice.map(a=>`<article class="item"><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p>${safe(a.url)?`<a href="${esc(a.url)}">Leer consejo</a>`:''}</article>`).join(''):empty('Próximamente, consejos profesionales.'));
html+=section('LA HISTORIA DETRÁS DEL NEGOCIO',b.story?`<p>${esc(b.story)}</p>${b.startYear?`<p>Desde ${esc(b.startYear)}</p>`:''}${b.founders?`<p>${esc(b.founders)}</p>`:''}${b.anecdotes?`<p>${esc(b.anecdotes)}</p>`:''}<div class="gallery">${(b.historyPhotos||[]).map(p=>image(p,'Fotografía de la historia del negocio')).join('')}</div>`:empty('Próximamente, la historia y trayectoria de este negocio.'));
if(b.photos?.length)html+=section('FOTOGRAFÍAS',`<div class="gallery">${b.photos.map(p=>image(p,b.name)).join('')}</div>`);html+=section('RESEÑAS',(b.reviews||[]).filter(r=>r.approved).map(r=>`<blockquote>${esc(r.text)}<footer>${esc(r.name)}</footer></blockquote>`).join('')||empty('Todavía no hay reseñas publicadas.'));
html+=section('CONTACTO',contact(b.type==='realEstate'?'HABLAR CON MORAVIA POR WHATSAPP':'CONSULTAR POR WHATSAPP','Hola, vi tu ficha en Revista Montevideo y quiero consultar.')+`<p><a data-track="phone" href="tel:+${phone}">${esc(b.phone)}</a></p>`+(safe(b.instagram)?`<p><a data-track="instagram" href="${esc(b.instagram)}" target="_blank" rel="noopener">Instagram</a></p>`:'')+(safe(b.website)?`<p><a data-track="website" href="${esc(b.website)}" target="_blank" rel="noopener">Visitar web</a></p>`:'')+(b.email?`<p><a href="mailto:${esc(b.email)}">${esc(b.email)}</a></p>`:''));
html+=section('COMPARTÍ ESTA FICHA','<div id="qr"></div><p>El QR abre esta ficha de Revista Montevideo.</p><button class="btn" id="copy-link">Copiar enlace</button><p id="copy-status" role="status"></p>');const related=all.filter(x=>(b.related||[]).includes(x.id)&&x.status==='published');if(related.length)html+=section('NEGOCIOS RELACIONADOS',related.map(x=>`<a class="btn" href="/negocios/${esc(x.slug)}/">${esc(x.name)}</a>`).join(''));root.querySelector('#modules').innerHTML=html;document.querySelector('#show-all')?.addEventListener('click',e=>{root.querySelectorAll('[data-extra-item]').forEach(x=>x.hidden=false);e.target.hidden=true;track(cfg.key+'_view_all')});const url=new URL('/negocios/'+b.slug+'/',location.origin);url.searchParams.set('src','qr');const qr=document.querySelector('#qr');if(window.qrcode){const code=window.qrcode(0,'M');code.addData(url.href);code.make();qr.innerHTML=code.createImgTag(5,8);qr.querySelector('img').alt='QR de la ficha de '+b.name;qr.querySelector('img').className='qr'}else qr.textContent='Enlace de la ficha: '+url.href;document.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(new URL('/negocios/'+b.slug+'/',location.origin).href);document.querySelector('#copy-status').textContent='Enlace copiado.'}catch{document.querySelector('#copy-status').textContent=new URL('/negocios/'+b.slug+'/',location.origin).href}};
})();
